Here is the commit message:
net: ti: icssg-prueth: fix use-after-free of CPPI descriptor
 in RX path

cppi5_hdesc_get_psdata() returns a pointer into the CPPI descriptor.
In both emac_rx_packet() and emac_rx_packet_zc(), the descriptor is
freed via k3_cppi_desc_pool_free() before the psdata pointer is used
by emac_rx_timestamp(), which dereferences psdata[0] and psdata[1].
This constitutes a use-after-free on every received packet that goes
through the timestamp path.

Defer the descriptor free until after all accesses through the psdata
pointer are complete. For emac_rx_packet(), move the free into the
requeue label so both early-exit and success paths free the descriptor
after all accesses are done. For emac_rx_packet_zc(), move the free to
the end of the loop body after emac_dispatch_skb_zc() (which calls
emac_rx_timestamp()) has returned.

Fixes: 46eeb90f03e0 ("net: ti: icssg-prueth: Use page_pool API for RX buffer allocation")
Signed-off-by: David Carlier <devnexen@gmail.com>
Reviewed-by: Simon Horman <horms@kernel.org>
Link: https://patch.msgid.link/20260320174439.41080-1-devnexen@gmail.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The CPPI descriptor was freed via `k3_cppi_desc_pool_free()` before the `psdata` pointer (obtained via `cppi5_hdesc_get_psdata()`) was used by `emac_rx_timestamp()`, leading to a use-after-free on every received packet in the timestamp path. The fix defers the descriptor free until after all accesses through the `psdata` pointer are complete.

Here is the patch:

 static int emac_rx_packet_zc(struct prueth_emac *emac, u32 flow_id,
 			     int budget)
 {
 	struct prueth_rx_chn *rx_chn = &emac->rx_chns;
 	u32 buf_dma_len, pkt_len, port_id = 0;
 	struct net_device *ndev = emac->ndev;
 	struct cppi5_host_desc_t *desc_rx;
 	struct prueth_swdata *swdata;
 	dma_addr_t desc_dma, buf_dma;
 	struct xdp_buff *xdp;
 	int xdp_status = 0;
 	int count = 0;
 	u32 *psdata;
 	int ret;

 	while (count < budget) {
 		ret = k3_udma_glue_pop_rx_chn(rx_chn->rx_chn, flow_id, &desc_dma);
 		if (ret) {
 			if (ret != -ENODATA)
 				netdev_err(ndev, "rx pop: failed: %d\n", ret);
 			break;
 		}

 		if (cppi5_desc_is_tdcm(desc_dma)) {
 			complete(&emac->tdown_complete);
 			break;
 		}

 		desc_rx = k3_cppi_desc_pool_dma2virt(rx_chn->desc_pool, desc_dma);
 		swdata = cppi5_hdesc_get_swdata(desc_rx);
 		if (swdata->type != PRUETH_SWDATA_XSK) {
 			netdev_err(ndev, "rx_pkt: invalid swdata->type %d\n", swdata->type);
 			k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);
 			break;
 		}

 		xdp = swdata->data.xdp;
 		cppi5_hdesc_get_obuf(desc_rx, &buf_dma, &buf_dma_len);
 		k3_udma_glue_rx_cppi5_to_dma_addr(rx_chn->rx_chn, &buf_dma);
 		pkt_len = cppi5_hdesc_get_pktlen(desc_rx);
 		/* firmware adds 4 CRC bytes, strip them */
 		pkt_len -= 4;
 		cppi5_desc_get_tags_ids(&desc_rx->hdr, &port_id, NULL);
 		psdata = cppi5_hdesc_get_psdata(desc_rx);
-		k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);
 		count++;
 		xsk_buff_set_size(xdp, pkt_len);
 		xsk_buff_dma_sync_for_cpu(xdp);

 		if (prueth_xdp_is_enabled(emac)) {
 			ret = emac_run_xdp(emac, xdp, &pkt_len);
 			switch (ret) {
 			case ICSSG_XDP_PASS:
 				/* prepare skb and send to n/w stack */
 				emac_dispatch_skb_zc(emac, xdp, psdata);
 				xsk_buff_free(xdp);
 				break;
 			case ICSSG_XDP_CONSUMED:
 				xsk_buff_free(xdp);
 				break;
 			case ICSSG_XDP_TX:
 			case ICSSG_XDP_REDIR:
 				xdp_status |= ret;
 				break;
 			}
 		} else {
 			/* prepare skb and send to n/w stack */
 			emac_dispatch_skb_zc(emac, xdp, psdata);
 			xsk_buff_free(xdp);
 		}
+		k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);
 	}

 	if (xdp_status & ICSSG_XDP_REDIR)
 		xdp_do_flush();

 	/* Allocate xsk buffers from the pool for the "count" number of
 	 * packets processed in order to be able to receive more packets.
 	 */
 	ret = prueth_rx_alloc_zc(emac, count);

 	if (xsk_uses_need_wakeup(rx_chn->xsk_pool)) {
 		/* If the user space doesn't provide enough buffers then it must
 		 * explicitly wake up the kernel when new buffers are available
 		 */
 		if (ret < count)
 			xsk_set_rx_need_wakeup(rx_chn->xsk_pool);
 		else
 			xsk_clear_rx_need_wakeup(rx_chn->xsk_pool);
 	}

 	return count;
 }

 static int emac_rx_packet(struct prueth_emac *emac, u32 flow_id, u32 *xdp_state)
 {
 	struct prueth_rx_chn *rx_chn = &emac->rx_chns;
 	u32 buf_dma_len, pkt_len, port_id = 0;
 	struct net_device *ndev = emac->ndev;
 	struct cppi5_host_desc_t *desc_rx;
 	struct prueth_swdata *swdata;
 	dma_addr_t desc_dma, buf_dma;
 	struct page *page, *new_page;
 	struct page_pool *pool;
 	struct sk_buff *skb;
 	struct xdp_buff xdp;
 	int headroom, ret;
 	u32 *psdata;
 	void *pa;

 	*xdp_state = 0;
 	pool = rx_chn->pg_pool;
 	ret = k3_udma_glue_pop_rx_chn(rx_chn->rx_chn, flow_id, &desc_dma);
 	if (ret) {
 		if (ret != -ENODATA)
 			netdev_err(ndev, "rx pop: failed: %d\n", ret);
 		return ret;
 	}

 	if (cppi5_desc_is_tdcm(desc_dma)) {
 		complete(&emac->tdown_complete);
 		return 0;
 	}

 	desc_rx = k3_cppi_desc_pool_dma2virt(rx_chn->desc_pool, desc_dma);
 	swdata = cppi5_hdesc_get_swdata(desc_rx);
 	if (swdata->type != PRUETH_SWDATA_PAGE) {
 		netdev_err(ndev, "rx_pkt: invalid swdata->type %d\n", swdata->type);
 		k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);
 		return 0;
 	}

 	page = swdata->data.page;
 	page_pool_dma_sync_for_cpu(pool, page, 0, PAGE_SIZE);
 	cppi5_hdesc_get_obuf(desc_rx, &buf_dma, &buf_dma_len);
 	k3_udma_glue_rx_cppi5_to_dma_addr(rx_chn->rx_chn, &buf_dma);
 	pkt_len = cppi5_hdesc_get_pktlen(desc_rx);
 	/* firmware adds 4 CRC bytes, strip them */
 	pkt_len -= 4;
 	cppi5_desc_get_tags_ids(&desc_rx->hdr, &port_id, NULL);
-	k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);

 	/* if allocation fails we drop the packet but push the
 	 * descriptor back to the ring with old page to prevent a stall
 	 */
 	new_page = page_pool_dev_alloc_pages(pool);
 	if (unlikely(!new_page)) {
 		new_page = page;
 		ndev->stats.rx_dropped++;
 		goto requeue;
 	}

 	pa = page_address(page);
 	if (prueth_xdp_is_enabled(emac)) {
 		xdp_init_buff(&xdp, PAGE_SIZE, &rx_chn->xdp_rxq);
 		xdp_prepare_buff(&xdp, pa, PRUETH_HEADROOM, pkt_len, false);

 		*xdp_state = emac_run_xdp(emac, &xdp, &pkt_len);
 		if (*xdp_state == ICSSG_XDP_CONSUMED) {
 			page_pool_recycle_direct(pool, page);
 			goto requeue;
 		}

 		if (*xdp_state != ICSSG_XDP_PASS)
 			goto requeue;
 		headroom = xdp.data - xdp.data_hard_start;
 		pkt_len = xdp.data_end - xdp.data;
 	} else {
 		headroom = PRUETH_HEADROOM;
 	}

 	/* prepare skb and send to n/w stack */
 	skb = napi_build_skb(pa, PAGE_SIZE);
 	if (!skb) {
 		ndev->stats.rx_dropped++;
 		page_pool_recycle_direct(pool, page);
 		goto requeue;
 	}

 	skb_reserve(skb, headroom);
 	skb_put(skb, pkt_len);
 	skb->dev = ndev;

 	psdata = cppi5_hdesc_get_psdata(desc_rx);
 	/* RX HW timestamp */
 	if (emac->rx_ts_enabled)
 		emac_rx_timestamp(emac, skb, psdata);

 	if (emac->prueth->is_switch_mode)
 		skb->offload_fwd_mark = emac->offload_fwd_mark;
 	skb->protocol = eth_type_trans(skb, ndev);

 	skb_mark_for_recycle(skb);
 	napi_gro_receive(&emac->napi_rx, skb);
 	ndev->stats.rx_bytes += pkt_len;
 	ndev->stats.rx_packets++;

 requeue:
+	k3_cppi_desc_pool_free(rx_chn->desc_pool, desc_rx);
 	/* queue another RX DMA */
 	ret = prueth_dma_rx_push_mapped(emac, &emac->rx_chns, new_page,
 					PRUETH_MAX_PKT_SIZE);
 	if (WARN_ON(ret < 0)) {
 		page_pool_recycle_direct(pool, new_page);
 		ndev->stats.rx_errors++;
 		ndev->stats.rx_dropped++;
 	}

 	return ret;
 }



